gsap.registerPlugin(ScrollTrigger, SplitText);

  // Só entrada (sem scrub)
  const SELECTOR = '.efeito-entrada .elementor-heading-title';

  function getColor(h2) {
    return '#C8FF32'; // cor da "barra" (ajuste aqui)
  }

  function buildFor(h2){
    if (h2.__st)    { h2.__st.kill(); h2.__st = null; }
    if (h2.__split) { h2.__split.revert(); h2.__split = null; }

    const split = new SplitText(h2, { type: 'lines', linesClass: '__reveal-line' });
    h2.__split = split;

    const color = getColor(h2);
    const cs = getComputedStyle(h2);
    const ta = cs.textAlign;
    const lh = cs.lineHeight;

    split.lines.forEach(line => {
      const base = {
        position: 'relative',
        overflow: 'hidden',
        clipPath: 'inset(0% 100% 0% 0%)',
        ...(lh !== 'normal' ? { lineHeight: lh } : {})
      };

      if (ta === 'center') {
        gsap.set(line, {
          ...base,
          display: 'inline-block',
          marginLeft: 'auto',
          marginRight: 'auto',
          verticalAlign: 'top'
        });
      } else {
        gsap.set(line, {
          ...base,
          display: 'block',
          width: 'fit-content'
        });
      }

      const bar = document.createElement('em');
      line.appendChild(bar);
      gsap.set(bar, {
        position: 'absolute',
        zIndex: 2,
        top: 0,
        left: 0,
        right: 0,
        bottom: 0,
        backgroundColor: color,
        pointerEvents: 'none'
      });
    });

    const bars = split.lines.map(l => l.querySelector('em'));

    const tl = gsap.timeline({
      scrollTrigger: {
        trigger: h2,
        start: 'top 90%',
        toggleActions: 'play none none none',
        once: true
      }
    });

    tl.to(split.lines, {
      clipPath: 'inset(0% 0% 0% 0%)',
      ease: 'power3.out',
      duration: 0.8,
      stagger: 0.2
    }, 0);

    tl.to(bars, {
      left: '100%',
      ease: 'power3.out',
      duration: 0.8,
      stagger: 0.2
    }, 0.4);

    gsap.set(h2, { opacity: 1 });
    h2.__st = tl;
  }

  function initAll(){
    document.querySelectorAll(SELECTOR).forEach(buildFor);
    ScrollTrigger.refresh();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initAll);
  } else {
    initAll();
  }

const lazyloadRunObserver = () => {
					const lazyloadBackgrounds = document.querySelectorAll( `.e-con.e-parent:not(.e-lazyloaded)` );
					const lazyloadBackgroundObserver = new IntersectionObserver( ( entries ) => {
						entries.forEach( ( entry ) => {
							if ( entry.isIntersecting ) {
								let lazyloadBackground = entry.target;
								if( lazyloadBackground ) {
									lazyloadBackground.classList.add( 'e-lazyloaded' );
								}
								lazyloadBackgroundObserver.unobserve( entry.target );
							}
						});
					}, { rootMargin: '200px 0px 200px 0px' } );
					lazyloadBackgrounds.forEach( ( lazyloadBackground ) => {
						lazyloadBackgroundObserver.observe( lazyloadBackground );
					} );
				};
				const events = [
					'DOMContentLoaded',
					'elementor/lazyload/observe',
				];
				events.forEach( ( event ) => {
					document.addEventListener( event, lazyloadRunObserver );
				} );

